        elif unavailable=='expiry':u['engine'].clock=lambda:datetime(2100,1,1,tzinfo=timezone.utc)
        else:delattr(u['f'][0],'_isolated_template_migration_checker')
        page=plan_read(u['f'],p);assert page.status_code==200,page.text
